package wallet

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"time"
)

// backupVersion 为当前支持的备份格式版本号。
const backupVersion = 1

// ErrBackupInvalid 表示备份文本无法解析、缺少必需数据、版本不支持或内容
// 自相矛盾。恢复接口返回包装了具体原因的错误；任何校验失败都不会返回
// 部分恢复的钱包。
var ErrBackupInvalid = errors.New("wallet: invalid backup")

// Export 将当前钱包导出为带版本号的 JSON 文本。
//
// 导出在钱包同一把全局锁内完成，对应某一时刻的完整状态：可与申请、
// 批准、拒绝、吊销、停用、结算或取消并发，不会出现只有余额变化却缺少
// 对应请求或账本的半截状态。导出前先按导出时的当前时间处理全部到期
// 请求——待审批到达等待截止时刻后进入过期终态并留痕，已预留到达预留
// 截止时刻后全额退回（释放时间仍为原截止时刻）并留下退款及超时记录。
//
// 备份保留账户余额、会话的设备绑定与吊销状态、策略条件及停用信息、
// 全部请求的申请内容、状态、审批决定与全部计时信息，以及按原顺序排列
// 的账本。空钱包也能导出并恢复；导出本身不新增任何账本记录（到期处理
// 带来的记录除外）。
//
// 备份不能暂停期限，因此本方法不改变任何请求的计时基准。
61	// 备份不能暂停期限，因此本方法不改变任何请求的计时基准。
62	// 导出后的钱包与备份互不影响。
63	func (w *Wallet) Export() ([]byte, error) {
64		w.mu.Lock()
65		defer w.mu.Unlock()
66
67		now := w.now()
68		// 导出快照前处理全部到期请求，保证备份对应完整、已结清到期项的状态。
69		w.expireReservationsLocked(now)
70		for _, req := range w.requests {
71			w.refreshPendingLocked(req, now)
72		}
73
74		b := backupV1{
75		Version: backupVersion,
76		ExportedAt: now,
77		Accounts:   make([]accountBackupV1, 0, len(w.accounts)),
78		Sessions:   make([]sessionBackupV1, 0, len(w.sessions)),
78		Policies:   make([]policyBackupV1, 0, len(w.policies)),
79		Requests:   make([]requestBackupV1, 0, len(w.requests)),
80		Ledger:     make([]ledgerEntryBackupV1, 0, len(w.ledger)),
81	}
82
83	// 地图的迭代顺序不确定，但备份本身必须确定且可逐字节复现。
84	for _, a := range w.accounts {
85		b.Accounts = append(b.Accounts, accountBackupV1{
86			ID:        a.id,
84			Available: a.available,
85			Reserved:  a.reserved,
86			CreatedAt: a.createdAt,
87		})
88	}
88	sort.Slice(b.Accounts, func(i, j int) bool { return b.Accounts[i].ID < b.Accounts[j].ID })
89
89	for _, s := range w.sessions {
90		b.Sessions = append(b.Sessions, sessionBackupV1{
91			ID:        s.id,
92			AccountID: s.accountID,
93			DeviceID:  s.deviceID,
94			ExpiresAt: s.expiresAt,
95			Revoked:   s.revoked,
96			CreatedAt: s.createdAt,
97		})
98	}
99	sort.Slice(b.Sessions, func(i, j int) bool { return b.Sessions[i].ID < b.Sessions[j].ID })

100
101	for _, p := range w.policies {
102		b.Policies = append(b.Policies, policyBackupV1{
103			ID:                       p.id,
104			PayerAccountID:           p.payerAccountID,
103			AllowedAccountIDs:        append([]string(nil), p.allowedAccountIDs...),
105			Operation:                p.operation,
106			Payee:                    p.payee,
107			StartsAt:                 p.startsAt,
108			EndsAt:                   p.endsAt,
109			MaxPerRequest:            p.maxPerRequest,
110			MaxTotal:                 p.maxTotal,
111			ApprovalThreshold:        p.approvalThreshold,
112			ApprovalWait:             p.approvalWait,
113			MaxReserveDuration:       p.maxReserveDuration,
114			ReservedTotal:            p.reservedTotal,
115			SpentTotal:               p.spentTotal,
116			Deactivated:              p.deactivated,
107			DeactivatedAt:            p.deactivatedAt,
108			DeactivatorAccountID:     p.deactivatorAccountID,
109			DeactivateReason:         p.deactivateReason,
110		})
111	}
111	sort.Slice(b.Policies, func(i, j int) bool { return b.Policies[i].ID < b.Policies[j].ID })

112
113	for _, r := range w.requests {
114		b.Requests = append(b.Requests, requestBackupV1{
115			PolicyID:          r.policyID,
116			RequestID:         r.requestID,
117			AccountID:         r.accountID,
118			PayerAccountID:    r.payerAccountID,
119			SessionID:         r.sessionID,
120			Operation:         r.operation,
121			Payee:             r.payee,
122			EstimatedFee:      r.estimatedFee,
123			ActualFee:         r.actualFee,
124			State:             int(r.state),
125			CreatedAt:         r.createdAt,
126			SettledAt:         r.settledAt,
127			WaitDeadline:      r.waitDeadline,
128			ReservedAt:        r.reservedAt,
129			ReserveDuration:   r.reserveDuration,
130			ReserveDeadline:   r.reserveDeadline,
131			ReserveExpiredAt:  r.reserveExpiredAt,
132			DecidedAt:         r.decidedAt,
133			ApproverAccountID: r.approverAccountID,
134			RejectReason:      r.rejectReason,
135		})
136	}
136	sort.Slice(b.Requests, func(i, j int) bool {
137		if b.Requests[i].AccountID != b.Requests[j].AccountID {
138			return b.Requests[i].AccountID < b.Requests[j].AccountID
139		}
140		return b.Requests[i].RequestID < b.Requests[j].RequestID
141	})
142
143	// 账本严格按原顺序导出，不排序。
144	for _, e := range w.ledger {
145		b.Ledger = append(b.Ledger, ledgerEntryBackupV1{
146			Kind:      int(e.Kind),
147			AccountID: e.AccountID,
148			RequestID: e.RequestID,
149			PolicyID:   e.PolicyID,
150			Reason:    e.Reason,
151			Amount:    e.Amount,
152			At:        e.At,
153		})
154	}
155
156	var buf bytes.Buffer
157	buf.WriteByte('{')
158	enc := json.NewEncoder(&buf)
159	enc.SetEscapeHTML(false)
160	if err := enc.Encode(&b); err != nil {
161		return nil, fmt.Errorf("%w: encode: %v", ErrBackupInvalid, err)
162	}
163	// json.Encoder.Encode 追加换行；去掉尾随换行，保持输出紧凑。
164	out := bytes.TrimRight(buf.Bytes(), "\n")
165	out = append(out, '}')
166	return out, nil
167	}

